INSERT INTO "metabase_table" ("id", "created_at", "updated_at", "name", "description", "entity_type", "active", "db_id", "display_name", "visibility_type", "schema", "points_of_interest", "caveats", "show_in_getting_started", "field_order", "initial_sync_status", "is_upload", "database_require_filter", "estimated_row_count", "view_count", "is_defective_duplicate", "deactivated_at", "archived_at", "is_writable", "data_authority", "data_source", "data_layer", "owner_email", "owner_user_id", "collection_id", "is_published", "transform_id", "transform_target") VALUES (4, '2026-09-24 00:00:00.000000', '2026-09-24 00:00:00.000000', 'REVIEWS', 'Reviews that Sample Company customers have left on our products.', 'entity/GenericTable', 1, 1, 'Reviews', NULL, NULL, 'Is it? You tell us!', 'These reviews aren''t tied to orders so it is possible people have reviewed products they did not purchase from us.', 0, 'database', 'complete', 0, NULL, NULL, 0, 0, NULL, NULL, NULL, 'unconfigured', NULL, 'final', NULL, NULL, NULL, 0, NULL, 0);

INSERT INTO "metabase_table" ("id", "created_at", "updated_at", "name", "description", "entity_type", "active", "db_id", "display_name", "visibility_type", "schema", "points_of_interest", "caveats", "show_in_getting_started", "field_order", "initial_sync_status", "is_upload", "database_require_filter", "estimated_row_count", "view_count", "is_defective_duplicate", "deactivated_at", "archived_at", "is_writable", "data_authority", "data_source", "data_layer", "owner_email", "owner_user_id", "collection_id", "is_published", "transform_id", "transform_target") VALUES (5, '2026-09-24 00:00:00.000000', '2026-09-24 00:00:00.000000', 'FEEDBACK', 'With each order of pies sent out, Piespace includes a place for customers to submit feedback and review their order.', 'entity/GenericTable', 1, 1, 'Feedback', NULL, NULL, 'Is it? We’ll let you be the judge of that.', 'Not every account feels inclined to submit feedback. That’s cool. There’s still quite a few responses here.', 0, 'database', 'complete', 0, NULL, NULL, 0, 0, NULL, NULL, NULL, 'unconfigured', NULL, 'final', NULL, NULL, NULL, 0, NULL, 0);

INSERT INTO "metabase_table" ("id", "created_at", "updated_at", "name", "description", "entity_type", "active", "db_id", "display_name", "visibility_type", "schema", "points_of_interest", "caveats", "show_in_getting_started", "field_order", "initial_sync_status", "is_upload", "database_require_filter", "estimated_row_count", "view_count", "is_defective_duplicate", "deactivated_at", "archived_at", "is_writable", "data_authority", "data_source", "data_layer", "owner_email", "owner_user_id", "collection_id", "is_published", "transform_id", "transform_target") VALUES (6, '2026-09-24 00:00:00.000000', '2026-09-24 00:00:00.000000', 'ACCOUNTS', 'Information on customer accounts registered with Piespace. Each account represents a new organization signing up for on-demand pies.', 'entity/UserTable', 1, 1, 'Accounts', NULL, NULL, 'Is it? We’ll let you be the judge of that.', 'Piespace’s business operates with a two week trial period. If you see that “Canceled At” is null then that account is still happily paying for their pies.', 0, 'database', 'complete', 0, NULL, NULL, 0, 0, NULL, NULL, NULL, 'unconfigured', NULL, 'final', NULL, NULL, NULL, 0, NULL, 0);

INSERT INTO "metabase_table" ("id", "created_at", "updated_at", "name", "description", "entity_type", "active", "db_id", "display_name", "visibility_type", "schema", "points_of_interest", "caveats", "show_in_getting_started", "field_order", "initial_sync_status", "is_upload", "database_require_filter", "estimated_row_count", "view_count", "is_defective_duplicate", "deactivated_at", "archived_at", "is_writable", "data_authority", "data_source", "data_layer", "owner_email", "owner_user_id", "collection_id", "is_published", "transform_id", "transform_target") VALUES (7, '2026-09-24 00:00:00.000000', '2026-09-24 00:00:00.000000', 'ANALYTIC_EVENTS', 'Piespace does some anonymous analytics tracking on how users interact with their platform. They’ve only had time to implement a few events, but you know how it is. Pies come first.', 'entity/EventTable', 1, 1, 'Analytic Events', NULL, NULL, 'Is it? We’ll let you be the judge of that.', 'Piespace has cracked time travel, so keep in mind that some events may have already happened in the future.', 0, 'database', 'complete', 0, NULL, NULL, 0, 0, NULL, NULL, NULL, 'unconfigured', NULL, 'final', NULL, NULL, NULL, 0, NULL, 0);

