CREATE VIEW "v_agent_api_calls" AS
SELECT
    "t"."id" AS "call_id",
    "t"."created_at",
    "t"."operation",
    "t"."status",
    "t"."error_message" AS "error_message",
    "t"."duration_ms",
    "t"."user_id",
    COALESCE("u"."first_name" || ' ' || "u"."last_name", "u"."email") AS "user_display_name",
    (SELECT
        "pg"."name"
    FROM "permissions_group_membership" "pgm"
    INNER JOIN "permissions_group" "pg"
        ON 1=1
    WHERE ("pgm"."user_id" = "t"."user_id")
        AND ("pg"."id" <> 1)
        AND ("pg"."id" = "pgm"."group_id")
    ORDER BY 1
    LIMIT 1) AS "group_name",
    "t"."client_name" AS "client_name",
    CASE "t"."client_name" WHEN 'metabase-cli' THEN 'Metabase CLI' WHEN 'other' THEN 'Other' ELSE "t"."client_name" END AS "client_display_name",
    "t"."tenant_id" AS "tenant_id",
    "tn"."name" AS "tenant_name",
    "t"."ip_address" AS "ip_address"
FROM "agent_api_call_log" "t"
LEFT OUTER JOIN "core_user" "u"
    ON "u"."id" = "t"."user_id"
LEFT OUTER JOIN "tenant" "tn"
    ON "tn"."id" = "t"."tenant_id";

CREATE VIEW "v_ai_usage_log" AS
SELECT
    "a"."id" AS "usage_log_id",
    "a"."created_at",
    "a"."source",
    CASE "a"."source" WHEN 'metabot_agent' THEN 'Metabot' WHEN 'agent' THEN 'Metabot' WHEN 'contextual_interestingness' THEN 'Research' WHEN 'exploration' THEN 'Research' WHEN 'document_generate_content' THEN 'Documents' WHEN 'example_question_generation_batch' THEN 'Suggested Prompts' WHEN 'slack' THEN 'Slackbot' WHEN 'slackbot' THEN 'Slackbot' WHEN 'oss-sql-gen' THEN 'SQL' WHEN 'sql-gen' THEN 'SQL' WHEN 'unknown' THEN 'Unknown' ELSE "a"."source" END AS "source_name",
    "a"."model",
    "a"."profile_id",
    "a"."prompt_tokens",
    "a"."completion_tokens",
    "a"."total_tokens",
    "a"."conversation_id",
    "a"."user_id",
    'user_' || "a"."user_id" AS "user_qualified_id",
    COALESCE("u"."first_name" || ' ' || "u"."last_name", "u"."email") AS "user_display_name",
    (SELECT
        "pg"."name"
    FROM "permissions_group_membership" "pgm"
    INNER JOIN "permissions_group" "pg"
        ON 1=1
    WHERE ("pgm"."user_id" = "a"."user_id")
        AND ("pg"."id" <> 1)
        AND ("pg"."id" = "pgm"."group_id")
    ORDER BY 1
    LIMIT 1) AS "group_name",
    "c"."ip_address" AS "ip_address",
    "c"."embedding_hostname" AS "embedding_hostname",
    "c"."embedding_path" AS "embedding_path",
    "c"."user_agent" AS "user_agent",
    "c"."sanitized_user_agent" AS "sanitized_user_agent",
    "c"."forked_from_conversation_id" AS "forked_from_conversation_id",
    "a"."tenant_id",
    "a"."request_id",
    "a"."cache_creation_tokens",
    "a"."cache_read_tokens"
FROM "ai_usage_log" "a"
LEFT OUTER JOIN "core_user" "u"
    ON "u"."id" = "a"."user_id"
LEFT OUTER JOIN "metabot_conversation" "c"
    ON "c"."id" = "a"."conversation_id";

-- SQLite equivalent of instance_analytics_views/alerts/v4/h2-alerts.sql.
create view v_alerts as
with cron_fields as (
    select ns.*,
           json_extract('["' || replace(cron_schedule, ' ', '","') || '"]', '$[1]') as cron_minute,
           json_extract('["' || replace(cron_schedule, ' ', '","') || '"]', '$[2]') as cron_hour,
           json_extract('["' || replace(cron_schedule, ' ', '","') || '"]', '$[3]') as cron_monthday,
           json_extract('["' || replace(cron_schedule, ' ', '","') || '"]', '$[5]') as cron_weekday
    from notification_subscription ns
)
select
    n.id as entity_id,
    'notification_' || n.id as entity_qualified_id,
    n.created_at,
    n.updated_at,
    n.creator_id,
    nc.card_id,
    'card_' || nc.card_id as card_qualified_id,
    case
        when nc.send_condition = 'has_result' then 'rows'
        when nc.send_condition in ('goal_above', 'goal_below') then 'goal'
    end as alert_condition,
    case
        when ns.ui_display_type = 'cron/raw' then 'custom'
        when ns.cron_minute = '*' or
             (ns.cron_minute GLOB '[0-9]*/[0-9]*' and ns.cron_minute not glob '*[^0-9/]*' and length(ns.cron_minute) - length(replace(ns.cron_minute, '/', '')) = 1) then 'by the minute'
        when ns.cron_monthday != '*' and
             (ns.cron_weekday = '?' or
              ns.cron_weekday GLOB '[0-9]#1' or
              ns.cron_weekday GLOB '[0-9]L') then 'monthly'
        when ns.cron_weekday != '?' and
             ns.cron_weekday != '*' then 'weekly'
        when ns.cron_hour != '*' then 'daily'
        else 'hourly'
    end as schedule_type,
    case
        when ns.cron_weekday GLOB '1*' then 'sun'
        when ns.cron_weekday GLOB '2*' then 'mon'
        when ns.cron_weekday GLOB '3*' then 'tue'
        when ns.cron_weekday GLOB '4*' then 'wed'
        when ns.cron_weekday GLOB '5*' then 'thu'
        when ns.cron_weekday GLOB '6*' then 'fri'
        when ns.cron_weekday GLOB '7*' then 'sat'
        else null
    end as schedule_day,
    case
        when ns.cron_hour = '*' then null
        when (ns.cron_hour != '' and ns.cron_hour NOT GLOB '*[^0-9]*') then
            cast(ns.cron_hour as integer)
        when (ns.cron_hour GLOB '[0-9]*/[0-9]*' and ns.cron_hour not glob '*[^0-9/]*' and length(ns.cron_hour) - length(replace(ns.cron_hour, '/', '')) = 1) then
            cast(substr(ns.cron_hour, 1, instr(ns.cron_hour, '/') - 1) as integer)
        else null
    end as schedule_hour,
    not n.active as archived,
    nh.channel_type as recipient_type,
    (select GROUP_CONCAT(cu.email)
     from notification_recipient nr
     left join core_user cu on nr.user_id = cu.id and nr.type = 'notification-recipient/user'
     where nr.notification_handler_id = nh.id) as recipients,
    (select GROUP_CONCAT(nr.details)
     from notification_recipient nr
     where nr.notification_handler_id = nh.id
     and nr.type = 'notification-recipient/raw-value') as recipient_external
from notification n
join notification_card nc on n.payload_id = nc.id
join cron_fields ns on n.id = ns.notification_id
left join notification_handler nh on n.id = nh.notification_id
where n.payload_type = 'notification/card'
and ns.type = 'notification-subscription/cron';

CREATE VIEW "v_audit_log" AS
SELECT
    "id",
    CASE WHEN "topic" = 'card-create' THEN 'card-create' WHEN "topic" = 'card-delete' THEN 'card-delete' WHEN "topic" = 'card-update' THEN 'card-update' WHEN "topic" = 'pulse-create' THEN 'subscription-create' WHEN "topic" = 'pulse-delete' THEN 'subscription-delete' ELSE "topic" END AS "topic",
    "timestamp",
    NULL AS "end_timestamp",
    COALESCE("user_id", 0) AS "user_id",
    LOWER("model") AS "entity_type",
    "model_id" AS "entity_id",
    CASE WHEN "model" = 'Dataset' THEN CONCAT('card_', CAST("model_id" AS CHARACTER VARYING)) WHEN "model_id" IS NULL THEN NULL ELSE CONCAT(LOWER("model"), '_', "model_id") END AS "entity_qualified_id",
    "details"
FROM "audit_log"
WHERE "topic" NOT IN('card-read', 'card-query', 'dashboard-read', 'dashboard-query');

CREATE VIEW "v_content" AS
SELECT
    "action"."id" AS "entity_id",
    'action_' || "action"."id" AS "entity_qualified_id",
    'action' AS "entity_type",
    "created_at",
    "updated_at",
    "creator_id",
    "name",
    "description",
    CAST(NULL AS INTEGER) AS "collection_id",
    "made_public_by_id" AS "made_public_by_user",
    NULL AS "is_embedding_enabled",
    NULL AS "is_verified",
    "archived",
    "type" AS "action_type",
    "model_id" AS "action_model_id",
    NULL AS "collection_is_official",
    NULL AS "collection_is_personal",
    NULL AS "question_viz_type",
    NULL AS "question_database_id",
    NULL AS "question_is_native",
    CAST(NULL AS TIMESTAMP) AS "event_timestamp"
FROM "action"
UNION
SELECT
    "collection"."id" AS "entity_id",
    'collection_' || "collection"."id" AS "entity_qualified_id",
    'collection' AS "entity_type",
    "created_at",
    NULL AS "updated_at",
    NULL AS "creator_id",
    "name",
    "description",
    NULL AS "collection_id",
    NULL AS "made_public_by_user",
    NULL AS "is_embedding_enabled",
    NULL AS "is_verified",
    "archived",
    NULL AS "action_type",
    NULL AS "action_model_id",
    CASE WHEN "authority_level" = 'official' THEN TRUE ELSE FALSE END AS "collection_is_official",
    CASE WHEN "personal_owner_id" IS NOT NULL THEN TRUE ELSE FALSE END AS "collection_is_personal",
    NULL AS "question_viz_type",
    NULL AS "question_database_id",
    NULL AS "question_is_native",
    NULL AS "event_timestamp"
FROM "collection"
UNION
SELECT
    "report_card"."id" AS "entity_id",
    'card_' || "report_card"."id" AS "entity_qualified_id",
    "type" AS "entity_type",
    "created_at",
    "updated_at",
    "creator_id",
    "name",
    "description",
    "collection_id" AS "collection_id",
    "made_public_by_id" AS "made_public_by_user",
    "enable_embedding" AS "is_embedding_enabled",
    CASE WHEN "is_verified" THEN TRUE ELSE FALSE END AS "is_verified",
    "archived",
    NULL AS "action_type",
    NULL AS "action_model_id",
    NULL AS "collection_is_official",
    NULL AS "collection_is_personal",
    "display" AS "question_viz_type",
    'database_' || "database_id" AS "question_database_id",
    CASE WHEN "query_type" = 'native' THEN TRUE ELSE FALSE END AS "question_is_native",
    NULL AS "event_timestamp"
FROM "report_card"
LEFT OUTER JOIN (
    SELECT
        "moderated_item_type" || '_' || "moderated_item_id" AS "entity_qualified_id",
        CASE WHEN "status" = 'verified' THEN TRUE ELSE FALSE END AS "is_verified"
    FROM "moderation_review"
    WHERE "most_recent"
) "moderation"
    ON ('card_' || "report_card"."id") = "moderation"."entity_qualified_id"
UNION
SELECT
    "report_dashboard"."id" AS "entity_id",
    'dashboard_' || "report_dashboard"."id" AS "entity_qualified_id",
    'dashboard' AS "entity_type",
    "created_at",
    "updated_at",
    "creator_id",
    "name",
    "description",
    "collection_id" AS "collection_id",
    "made_public_by_id" AS "made_public_by_user",
    "enable_embedding" AS "is_embedding_enabled",
    CASE WHEN "is_verified" THEN TRUE ELSE FALSE END AS "is_verified",
    "archived",
    NULL AS "action_type",
    NULL AS "action_model_id",
    NULL AS "collection_is_official",
    NULL AS "collection_is_personal",
    NULL AS "question_viz_type",
    NULL AS "question_database_id",
    NULL AS "question_is_native",
    NULL AS "event_timestamp"
FROM "report_dashboard"
LEFT OUTER JOIN (
    SELECT
        "moderated_item_type" || '_' || "moderated_item_id" AS "entity_qualified_id",
        CASE WHEN "status" = 'verified' THEN TRUE ELSE FALSE END AS "is_verified"
    FROM "moderation_review"
    WHERE "most_recent"
) "moderation"
    ON ('dashboard_' || "report_dashboard"."id") = "moderation"."entity_qualified_id"
UNION
SELECT
    "document"."id" AS "entity_id",
    'document_' || "document"."id" AS "entity_qualified_id",
    'document' AS "entity_type",
    "created_at",
    "updated_at",
    "creator_id",
    "name",
    CAST(NULL AS CHARACTER VARYING) AS "description",
    "collection_id" AS "collection_id",
    CAST(NULL AS INTEGER) AS "made_public_by_user",
    NULL AS "is_embedding_enabled",
    NULL AS "is_verified",
    "archived",
    NULL AS "action_type",
    CAST(NULL AS INTEGER) AS "action_model_id",
    NULL AS "collection_is_official",
    NULL AS "collection_is_personal",
    NULL AS "question_viz_type",
    NULL AS "question_database_id",
    NULL AS "question_is_native",
    CAST(NULL AS TIMESTAMP) AS "event_timestamp"
FROM "document"
UNION
SELECT
    "event"."id" AS "entity_id",
    'event_' || "event"."id" AS "entity_qualified_id",
    'event' AS "entity_type",
    "event"."created_at",
    "event"."updated_at",
    "event"."creator_id",
    "event"."name",
    "event"."description",
    "timeline"."collection_id",
    NULL AS "made_public_by_user",
    NULL AS "is_embedding_enabled",
    NULL AS "is_verified",
    "event"."archived",
    NULL AS "action_type",
    NULL AS "action_model_id",
    NULL AS "collection_is_official",
    NULL AS "collection_is_personal",
    NULL AS "question_viz_type",
    NULL AS "question_database_id",
    NULL AS "question_is_native",
    "timestamp" AS "event_timestamp"
FROM "timeline_event" "event"
LEFT OUTER JOIN "timeline"
    ON "event"."timeline_id" = "timeline"."id"
UNION
SELECT
    "transform"."id" AS "entity_id",
    'transform_' || "transform"."id" AS "entity_qualified_id",
    'transform' AS "entity_type",
    "created_at",
    "updated_at",
    "creator_id",
    "name",
    "description",
    CAST(NULL AS INTEGER) AS "collection_id",
    CAST(NULL AS INTEGER) AS "made_public_by_user",
    NULL AS "is_embedding_enabled",
    NULL AS "is_verified",
    FALSE AS "archived",
    NULL AS "action_type",
    CAST(NULL AS INTEGER) AS "action_model_id",
    NULL AS "collection_is_official",
    NULL AS "collection_is_personal",
    NULL AS "question_viz_type",
    NULL AS "question_database_id",
    NULL AS "question_is_native",
    CAST(NULL AS TIMESTAMP) AS "event_timestamp"
FROM "transform"
UNION
SELECT
    "glossary"."id" AS "entity_id",
    'glossary_' || "glossary"."id" AS "entity_qualified_id",
    'glossary' AS "entity_type",
    "created_at",
    "updated_at",
    "creator_id",
    "term" AS "name",
    "definition" AS "description",
    CAST(NULL AS INTEGER) AS "collection_id",
    CAST(NULL AS INTEGER) AS "made_public_by_user",
    NULL AS "is_embedding_enabled",
    NULL AS "is_verified",
    FALSE AS "archived",
    NULL AS "action_type",
    CAST(NULL AS INTEGER) AS "action_model_id",
    NULL AS "collection_is_official",
    NULL AS "collection_is_personal",
    NULL AS "question_viz_type",
    NULL AS "question_database_id",
    NULL AS "question_is_native",
    CAST(NULL AS TIMESTAMP) AS "event_timestamp"
FROM "glossary";

CREATE VIEW "v_dashboardcard" AS
SELECT
    "id" AS "entity_id",
    (coalesce('dashboardcard_', '') || coalesce("id", '')) AS "entity_qualified_id",
    (coalesce('dashboard_', '') || coalesce("dashboard_id", '')) AS "dashboard_qualified_id",
    (coalesce('dashboardtab_', '') || coalesce("dashboard_tab_id", '')) AS "dashboardtab_id",
    (coalesce('card_', '') || coalesce("card_id", '')) AS "card_qualified_id",
    "created_at",
    "updated_at",
    "size_x",
    "size_y",
    "visualization_settings",
    "parameter_mappings"
FROM "report_dashboardcard";

CREATE VIEW "v_databases" AS
SELECT
    "id" AS "entity_id",
    (coalesce('database_', '') || coalesce("id", '')) AS "entity_qualified_id",
    "created_at",
    "updated_at",
    "name",
    "description",
    "engine" AS "database_type",
    "metadata_sync_schedule",
    "cache_field_values_schedule",
    "timezone",
    "is_on_demand",
    "auto_run_queries",
    "cache_ttl",
    "creator_id",
    "dbms_version" AS "db_version"
FROM "metabase_database"
WHERE "id" <> 13371337;

CREATE VIEW "v_fields" AS
SELECT
    "f"."id" AS "entity_id",
    'field_' || "f"."id" AS "entity_qualified_id",
    "f"."created_at",
    "f"."updated_at",
    "f"."name",
    COALESCE("u"."display_name", "f"."display_name") AS "display_name",
    CASE WHEN "u"."description_set" THEN "u"."description" ELSE "f"."description" END AS "description",
    "f"."base_type",
    COALESCE("u"."visibility_type", "f"."visibility_type") AS "visibility_type",
    CASE WHEN "u"."fk_target_field_id_set" THEN "u"."fk_target_field_id" ELSE "f"."fk_target_field_id" END AS "fk_target_field_id",
    COALESCE("u"."has_field_values", "f"."has_field_values") AS "has_field_values",
    "f"."active",
    "f"."table_id" AS "table_id"
FROM "metabase_field" "f"
LEFT OUTER JOIN "metabase_field_user_settings" "u"
    ON "u"."field_id" = "f"."id";

CREATE VIEW "v_group_members" AS
SELECT
    "user_id",
    "permissions_group"."id" AS "group_id",
    "permissions_group"."name" AS "group_name"
FROM "permissions_group_membership"
LEFT OUTER JOIN "permissions_group"
    ON "permissions_group_membership"."group_id" = "permissions_group"."id"
UNION
SELECT
    0 AS "user_id",
    0 AS "group_id",
    'Anonymous users' AS "group_name";

CREATE VIEW "v_mcp_tool_calls" AS
SELECT
    "t"."id" AS "tool_call_id",
    "t"."created_at",
    "t"."tool_name",
    "t"."status",
    CASE "t"."error_code" WHEN -32600 THEN 'Invalid request' WHEN -32601 THEN 'Method not found' WHEN -32602 THEN 'Invalid params' WHEN -32603 THEN 'Internal error' WHEN -32000 THEN 'Server error' ELSE NULL END AS "error_type",
    "t"."error_message" AS "error_message",
    "t"."duration_ms",
    "t"."user_id",
    COALESCE("u"."first_name" || ' ' || "u"."last_name", "u"."email") AS "user_display_name",
    (SELECT
        "pg"."name"
    FROM "permissions_group_membership" "pgm"
    INNER JOIN "permissions_group" "pg"
        ON 1=1
    WHERE ("pgm"."user_id" = "t"."user_id")
        AND ("pg"."id" <> 1)
        AND ("pg"."id" = "pgm"."group_id")
    ORDER BY 1
    LIMIT 1) AS "group_name",
    "t"."client_name" AS "client_name",
    CASE "t"."client_name" WHEN 'claude' THEN 'Claude' WHEN 'chatgpt' THEN 'ChatGPT' WHEN 'cursor-vscode' THEN 'Cursor' WHEN 'vscode' THEN 'VS Code' WHEN 'zed' THEN 'Zed' WHEN 'other' THEN 'Other' ELSE "t"."client_name" END AS "client_display_name",
    "t"."client_version" AS "client_version",
    "t"."tenant_id" AS "tenant_id",
    "tn"."name" AS "tenant_name",
    "t"."ip_address" AS "ip_address",
    "t"."user_agent" AS "user_agent",
    "t"."sanitized_user_agent" AS "sanitized_user_agent"
FROM "mcp_tool_call_log" "t"
LEFT OUTER JOIN "core_user" "u"
    ON "u"."id" = "t"."user_id"
LEFT OUTER JOIN "tenant" "tn"
    ON "tn"."id" = "t"."tenant_id";

CREATE VIEW "v_metabot_conversations" AS
SELECT
    "c"."id" AS "conversation_id",
    "c"."created_at",
    "c"."user_id",
    "c"."title",
    COALESCE("u"."first_name" || ' ' || "u"."last_name", "u"."email") AS "user_display_name",
    COUNT("m"."id") AS "message_count",
    COUNT(CASE WHEN "m"."role" = 'user' THEN 1 END) AS "user_message_count",
    COUNT(CASE WHEN "m"."role" = 'assistant' THEN 1 END) AS "assistant_message_count",
    COUNT(CASE WHEN "m"."forked_from_message_id" IS NULL THEN 1 END) AS "new_message_count",
    COALESCE(MAX("a"."total_tokens"), 0) AS "total_tokens",
    COALESCE(MAX("a"."prompt_tokens"), 0) AS "prompt_tokens",
    COALESCE(MAX("a"."completion_tokens"), 0) AS "completion_tokens",
    MAX("m"."created_at") AS "last_message_at",
    (SELECT
        "mm"."profile_id"
    FROM "metabot_message" "mm"
    WHERE ("mm"."role" = 'assistant')
        AND ("mm"."conversation_id" = "c"."id")
    ORDER BY "mm"."created_at", "mm"."id"
    LIMIT 1) AS "profile_id",
    (SELECT
        CASE "mm"."profile_id" WHEN 'internal' THEN 'Internal' WHEN 'embedding_next' THEN 'Embedding' WHEN 'nlq' THEN 'NLQ' WHEN 'sql' THEN 'SQL' WHEN 'slackbot' THEN 'Slackbot' WHEN 'transforms_codegen' THEN 'Transforms codegen' WHEN 'document-generate-content' THEN 'Documents' WHEN 'explorations' THEN 'Research' ELSE "mm"."profile_id" END
    FROM "metabot_message" "mm"
    WHERE ("mm"."role" = 'assistant')
        AND ("mm"."conversation_id" = "c"."id")
    ORDER BY "mm"."created_at", "mm"."id"
    LIMIT 1) AS "profile_name",
    (SELECT
        "pg"."name"
    FROM "permissions_group_membership" "pgm"
    INNER JOIN "permissions_group" "pg"
        ON 1=1
    WHERE ("pg"."id" = "pgm"."group_id")
        AND ("pg"."id" <> 1)
        AND ("pgm"."user_id" = "c"."user_id")
    ORDER BY 1
    LIMIT 1) AS "group_name",
    (SELECT
        "aul"."source"
    FROM "ai_usage_log" "aul"
    WHERE "aul"."conversation_id" = "c"."id"
    ORDER BY "aul"."created_at"
    LIMIT 1) AS "source",
    (SELECT
        CASE "aul"."source" WHEN 'metabot_agent' THEN 'Metabot' WHEN 'agent' THEN 'Metabot' WHEN 'document_generate_content' THEN 'Documents' WHEN 'example_question_generation_batch' THEN 'Suggested Prompts' WHEN 'slack' THEN 'Slackbot' WHEN 'slackbot' THEN 'Slackbot' WHEN 'oss-sql-gen' THEN 'SQL' WHEN 'sql-gen' THEN 'SQL' WHEN 'unknown' THEN 'Unknown' WHEN 'contextual_interestingness' THEN 'Research' WHEN 'exploration' THEN 'Research' ELSE "aul"."source" END
    FROM "ai_usage_log" "aul"
    WHERE "aul"."conversation_id" = "c"."id"
    ORDER BY "aul"."created_at"
    LIMIT 1) AS "source_name",
    "c"."ip_address" AS "ip_address",
    "c"."embedding_hostname" AS "embedding_hostname",
    "c"."embedding_path" AS "embedding_path",
    "c"."user_agent" AS "user_agent",
    "c"."sanitized_user_agent" AS "sanitized_user_agent",
    "c"."forked_from_conversation_id" AS "forked_from_conversation_id",
    MAX("a"."tenant_id") AS "tenant_id",
    MAX("t"."name") AS "tenant_name",
    (SELECT
        "aul"."model"
    FROM "ai_usage_log" "aul"
    WHERE "aul"."conversation_id" = "c"."id"
    ORDER BY "aul"."created_at"
    LIMIT 1) AS "model"
FROM "metabot_conversation" "c"
LEFT OUTER JOIN "core_user" "u"
    ON "u"."id" = "c"."user_id"
LEFT OUTER JOIN "metabot_message" "m"
    ON "m"."conversation_id" = "c"."id"
LEFT OUTER JOIN (
    SELECT
        "conversation_id",
        COALESCE(SUM("prompt_tokens"), 0) AS "prompt_tokens",
        COALESCE(SUM("completion_tokens"), 0) AS "completion_tokens",
        COALESCE(SUM("total_tokens"), 0) AS "total_tokens",
        MIN("tenant_id") AS "tenant_id"
    FROM "ai_usage_log"
    WHERE "conversation_id" IS NOT NULL
    GROUP BY "conversation_id"
) "a"
    ON "a"."conversation_id" = "c"."id"
LEFT OUTER JOIN "tenant" "t"
    ON "t"."id" = "a"."tenant_id"
GROUP BY "c"."id", "c"."created_at", "c"."user_id", "c"."title", "u"."first_name", "u"."last_name", "u"."email";

CREATE VIEW "v_metabot_messages" AS
SELECT
    "m"."id" AS "message_id",
    "m"."conversation_id",
    "m"."created_at",
    "m"."role",
    "m"."profile_id",
    "m"."total_tokens",
    COALESCE("m"."user_id", "c"."user_id") AS "user_id",
    "m"."slack_msg_id",
    "m"."channel_id"
FROM "metabot_message" "m"
INNER JOIN "metabot_conversation" "c"
    ON 1=1
WHERE ("m"."forked_from_message_id" IS NULL)
    AND ("c"."id" = "m"."conversation_id");

CREATE VIEW "v_query_log" AS
SELECT
    "id" AS "entity_id",
    "started_at",
    CAST("running_time" AS DOUBLE PRECISION) / 1000 AS "running_time_seconds",
    "result_rows",
    "native" AS "is_native",
    "context" AS "query_source",
    "error",
    COALESCE("executor_id", 0) AS "user_id",
    "card_id",
    'card_' || "card_id" AS "card_qualified_id",
    "dashboard_id",
    'dashboard_' || "dashboard_id" AS "dashboard_qualified_id",
    "pulse_id",
    "database_id",
    'database_' || "database_id" AS "database_qualified_id",
    "cache_hit",
    "action_id",
    'action_' || "action_id" AS "action_qualified_id",
    "transform_id",
    'transform_' || "transform_id" AS "transform_qualified_id",
    "lens_id",
    "lens_params",
    "query",
    "embedding_client",
    "embedding_client_identifier",
    "embedding_route",
    CASE WHEN "embedding_client" LIKE '%-preview' THEN TRUE ELSE FALSE END AS "is_preview",
    "embedding_sdk_version",
    "metabase_version",
    "auth_method",
    "is_sandboxed",
    "is_impersonated",
    "is_db_routed",
    "parameters",
    "tenant_id",
    "embedding_hostname",
    "embedding_path",
    "user_agent",
    "sanitized_user_agent",
    "ip_address"
FROM "query_execution"
LEFT OUTER JOIN "query"
    ON "query_execution"."hash" = "query"."query_hash";

CREATE VIEW "v_subscriptions" AS
SELECT
    "pulse"."id" AS "entity_id",
    'pulse_' || "pulse"."id" AS "entity_qualified_id",
    "pulse"."created_at",
    "pulse"."updated_at",
    "creator_id",
    "archived",
    'dashboard_' || "dashboard_id" AS "dashboard_qualified_id",
    "pulse_channel"."schedule_type",
    "pulse_channel"."schedule_day",
    "pulse_channel"."schedule_hour",
    "channel_type" AS "recipient_type",
    NULL AS "recipients",
    "details" AS "recipient_external",
    "parameters"
FROM "pulse"
LEFT OUTER JOIN "pulse_channel"
    ON "pulse"."id" = "pulse_channel"."pulse_id"
WHERE "alert_condition" IS NULL;

CREATE VIEW "v_tables" AS
SELECT
    "id" AS "entity_id",
    'table_' || "id" AS "entity_qualified_id",
    "created_at",
    "updated_at",
    "name",
    "display_name",
    "description",
    "active",
    "db_id" AS "database_id",
    "schema",
    "is_upload",
    "entity_type",
    "visibility_type",
    "estimated_row_count",
    "view_count",
    "owner_email",
    "owner_user_id"
FROM "metabase_table";

CREATE VIEW "v_tasks" AS
SELECT
    "id",
    "task",
    "status",
    'database_' || "db_id" AS "database_qualified_id",
    "started_at",
    "ended_at",
    CAST("duration" AS DOUBLE PRECISION) / 1000 AS "duration_seconds",
    "task_details" AS "details",
    "run_id"
FROM "task_history";

CREATE VIEW "v_task_runs" AS
SELECT
    "id",
    "run_type",
    "entity_type",
    "entity_id",
    CASE WHEN "entity_type" = 'database' THEN 'database_' || "entity_id" WHEN "entity_type" = 'card' THEN 'card_' || "entity_id" WHEN "entity_type" = 'dashboard' THEN 'dashboard_' || "entity_id" ELSE "entity_type" || '_' || "entity_id" END AS "entity_qualified_id",
    "started_at",
    "ended_at",
    CASE WHEN "ended_at" IS NOT NULL THEN CAST((unixepoch("ended_at") - unixepoch("started_at")) AS DOUBLE PRECISION) ELSE NULL END AS "duration_seconds",
    "status",
    "process_uuid",
    "updated_at"
FROM "task_run";

CREATE VIEW "v_tenants" AS
SELECT
    "id" AS "tenant_id",
    'tenant_' || "id" AS "entity_qualified_id",
    "name",
    "slug",
    "is_active",
    "attributes",
    "created_at",
    "updated_at",
    "tenant_collection_id",
    'collection_' || "tenant_collection_id" AS "tenant_collection_qualified_id"
FROM "tenant";

CREATE VIEW "v_users" AS
SELECT
    "id" AS "user_id",
    'user_' || "id" AS "entity_qualified_id",
    "type",
    CASE WHEN "type" = 'api-key' THEN NULL ELSE "email" END AS "email",
    "first_name",
    "last_name",
    COALESCE("first_name" || ' ' || "last_name", "first_name", "last_name") AS "full_name",
    "date_joined",
    "last_login",
    "updated_at",
    "is_superuser" AS "is_admin",
    "is_active",
    "sso_source",
    "locale",
    "tenant_id",
    'tenant_' || "tenant_id" AS "tenant_qualified_id"
FROM "core_user"
UNION
SELECT
    0 AS "user_id",
    'user_0' AS "entity_qualified_id",
    'anonymous' AS "type",
    NULL AS "email",
    'External' AS "first_name",
    'User' AS "last_name",
    'External User' AS "full_name",
    NULL AS "date_joined",
    NULL AS "last_login",
    NULL AS "updated_at",
    FALSE AS "is_admin",
    NULL AS "is_active",
    NULL AS "sso_source",
    NULL AS "locale",
    NULL AS "tenant_id",
    NULL AS "tenant_qualified_id";

CREATE VIEW "v_view_log" AS
SELECT
    "id",
    "timestamp",
    COALESCE("user_id", 0) AS "user_id",
    "model" AS "entity_type",
    "model_id" AS "entity_id",
    "model" || '_' || "model_id" AS "entity_qualified_id",
    "embedding_client",
    "embedding_client_identifier",
    "embedding_route",
    CASE WHEN "embedding_client" LIKE '%-preview' THEN TRUE ELSE FALSE END AS "is_preview",
    "has_access",
    "context",
    "embedding_sdk_version",
    "metabase_version",
    "auth_method",
    "tenant_id",
    "embedding_hostname",
    "embedding_path",
    "user_agent",
    "sanitized_user_agent",
    "ip_address"
FROM "view_log";
